function validate(input) {
  const [{ Teams = [], Matches = [] }] = input;
  const teams = new Set(), matches = new Set();
  for (const [id] of Teams) {
    if (id === null) return 'Every team needs a team_id.';
    if (teams.has(id)) return `team_id ${id} appears twice in Teams.`;
    teams.add(id);
  }
  for (const [id, host, guest, hostGoals, guestGoals] of Matches) {
    if (id === null) return 'Every match needs a match_id.';
    if (matches.has(id)) return `match_id ${id} appears twice in Matches.`;
    matches.add(id);
    if (!teams.has(host) || !teams.has(guest)) return `Match ${id} names a team missing from Teams.`;
    if (host === guest) return `Match ${id} has the same team as host and guest.`;
    if (hostGoals === null || guestGoals === null || hostGoals < 0 || guestGoals < 0) return `Match ${id} needs non-negative goal counts.`;
  }
  return null;
}

