function generate(rand, size) {
  const pick = (list) => list[Math.floor(rand() * list.length)];
  const names = ['Leetcode FC', 'NewYork FC', 'Atlanta FC', 'Chicago FC', 'Toronto FC', 'Austin FC'];
  const small = size === 'small';
  const teamCount = small ? Math.floor(rand() * 7) : 400;
  // Distinct ids in shuffled order, so the input order never matches the required order.
  const ids = [];
  for (let i = 1; i <= (small ? 9 : 2000); i++) ids.push(small ? i * 10 : i);
  for (let i = ids.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [ids[i], ids[j]] = [ids[j], ids[i]];
  }
  const Teams = ids.slice(0, teamCount).map((id) => [id, small ? pick(names) : `Team ${id}`]);
  const Matches = [];
  if (Teams.length >= 2) {
    const matchCount = small ? Math.floor(rand() * 9) : 2000;
    for (let id = 1; id <= matchCount; id++) {
      const host = Math.floor(rand() * Teams.length);
      let guest = Math.floor(rand() * (Teams.length - 1));
      if (guest >= host) guest++;
      const maxGoals = small ? 3 : 6;
      Matches.push([id, Teams[host][0], Teams[guest][0], Math.floor(rand() * (maxGoals + 1)), Math.floor(rand() * (maxGoals + 1))]);
    }
  }
  return [{ Teams, Matches }];
}
